import java.util.Scanner;

public class Main {
    static final int MAXN = 600;
    static long mod;
    static class Num {
        long v;
        Num() { v = 0; }
        Num(long _v) {
            v = _v % mod;
            if (v < 0) v += mod;
        }
        Num add(Num b) {
            return new Num((this.v + b.v) % mod);
        }
        Num sub(Num b) {
            return new Num((this.v - b.v + mod) % mod);
        }
        Num mul(Num b) {
            return new Num((this.v * b.v) % mod);
        }
        Num pow(long e) {
            Num res = new Num(1);
            Num base = new Num(this.v);
            while (e > 0) {
                if ((e & 1) == 1) res = res.mul(base);
                base = base.mul(base);
                e >>= 1;
            }
            return res;
        }
        Num inv() {
            return this.pow(mod - 2);
        }
    }

    static Num[][] C = new Num[MAXN + 1][MAXN + 1];
    static Num[] A = new Num[MAXN + 1], Cc = new Num[MAXN + 1];
    static Num[][][] DP = new Num[MAXN + 1][MAXN + 1][2], DPC = new Num[MAXN + 1][MAXN + 1][2];

    static long sum_range(long l, long r) {
        if (l > r) return 0;
        return (l + r) * (r - l + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextLong();

        for (int i = 0; i <= m; ++i) {
            for (int j = 0; j <= i; ++j) {
                if (j == 0 || j == i) {
                    C[i][j] = new Num(1);
                } else {
                    C[i][j] = C[i - 1][j - 1].add(C[i - 1][j]);
                }
            }
        }

        A[0] = new Num(0);
        Cc[0] = new Num(1);
        A[1] = new Num(0);
        Cc[1] = new Num(2);

        for (int i = 2; i <= m; ++i) {
            Num tmp = new Num(0);
            Num tmpc = new Num(0);
            for (int l = 0; l <= i; ++l) {
                int r = i - 1 - l;
                Num sumRange = new Num(sum_range(1, l) + sum_range(1, r));
                Num term1 = C[l][0].mul(C[r][0]).mul(sumRange).mul(C[i - 1][l]);
                Num term2 = (A[l].mul(C[r][0]).add(A[r].mul(C[l]))).mul(C[i - 1][l]).mul(new Num(i + 1));
                tmp = tmp.add(term1).add(term2);
                tmpc = tmpc.add(C[l][0].mul(C[r][0]).mul(new Num(i + 1)).mul(C[i - 1][l]));
            }
            A[i] = tmp;
            Cc[i] = tmpc;
        }

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                for (int k = 0; k < 2; ++k) {
                    DPC[i][j][k] = new Num(0);
                }
            }
        }
        DPC[0][0][0] = new Num(1);

        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                if (j > i) continue;
                DPC[i][j][0] = DPC[i - 1][j][0].add(DPC[i - 1][j][1]);
                for (int k = 1; k <= j; ++k) {
                    Num term = C[k][k].mul(C[j][k]).mul(DPC[i - k][j - k][0]);
                    DPC[i][j][1] = DPC[i][j][1].add(term);
                }
            }
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                if (j > i) continue;
                DP[i][j][0] = DP[i - 1][j][0].add(DP[i - 1][j][1]);
                for (int k = 1; k <= j; ++k) {
                    Num term1 = A[k].mul(C[j][k]).mul(DPC[i - k][j - k][0]);
                    Num term2 = DP[i - k][j - k][0].mul(Cc[k]).mul(C[j][k]);
                    DP[i][j][1] = DP[i][j][1].add(term1).add(term2);
                }
            }
        }

        Num result = DP[n][m][0].add(DP[n][m][1]);
        System.out.println(result.v);
        sc.close();
    }
}
